// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1000 ether);
        vm.deal(address(this), amount);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "funding failed");
        uint256 balanceBefore = address(c).balance;
        vm.prank(c.owner());
        bool success = true;
        try c.withdrawAll() {
        } catch {
            success = false;
        }
        assertTrue(!success || address(c).balance < balanceBefore);
    }
}
